final playingPathForShortcut = context.select<PlaybackController, String?>(
    (player) => player.songInfo?.track.path,
  );

  Future<void> _jumpToNowPlayingFromKeyboard() async {
    final playingPath = playingPathForShortcut;
    if (playingPath == null || playingPath!.isEmpty) return;
    final parent = p.dirname(playingPath!);
    if (parent.isEmpty) return;
    if (libCtrl.currentPath != parent) {
      await libCtrl.loadFolder(parent);
    }
    if (!isMounted()) return;
    await browserController.scrollToTrack(playingPath!);
  }

